int findIndex(int table[], int length, int wanted)
{
  int low = 0;
  int high = length - 1;
  while (low <= high)
  {
    int probe = low + (high - low) / 2;
    if (table[probe] == wanted)
      return probe;
    if (table[probe] < wanted)
      low = probe + 1;
    else
      high = probe - 1;
  }
  return -1;
}

